Object.assign(translations.en,{fachHeadline:"From measurements to settlement. One place for the whole renovation.",fachSummary:"Fachmetr helps tradespeople prepare estimates and keep track of scope, materials and deadlines — even without internet access.",discoverFach:"Discover Fachmetr",september2026:"September 2026",updateFachTitle:"The complete renovation workflow works in the prototype",updateFachCopy:"Clients, measurements, estimates, materials, settlements and the calendar are now connected in one mobile flow. We are testing it in practice.",navScreens:"Screens",fachHero:"Renovations under control.<br>From the first measurement.",fachLead:"Fachmetr is being made for tradespeople who want estimates, scope, materials, deadlines and settlement in one place.",seeHowItWorks:"See how it works",askFach:"Ask about Fachmetr",forWhom:"Who it is for",fachProblem:"Less searching through messages. More time for good work.",fachProblemCopy:"Solo tradespeople and small crews often manage a renovation across a notebook, messenger and several spreadsheets. Fachmetr brings it into one clear job history — from the client to final settlement.",fachWhat:"What it organises",fachOnePlace:"The whole renovation.<br>One simple workflow.",fachFeatureIntro:"Fachmetr is still in development. The features shown describe the working prototype and the current product direction.",fachFeatEstimate:"Measurements and estimates",fachFeatEstimateCopy:"Items, quantities and prices gathered into a clear estimate for a specific client.",fachFeatScope:"A clear scope",fachFeatScopeCopy:"The accepted baseline and later changes shown separately, so agreements do not get lost.",fachFeatMoney:"Materials and settlement",fachFeatMoneyCopy:"Client payments, material expenses and the amount due in one summary.",fachFeatCalendar:"Deadlines and reminders",fachFeatCalendarCopy:"A project calendar keeps stages, payments and meetings in view.",fachFeatDocs:"Documents for the client",fachFeatDocsCopy:"Organised estimates and summaries ready to share with the client.",fachFeatOffline:"Work without internet",fachFeatOfflineCopy:"The current project works locally on the device, without an account or constant internet access.",fachScreensTitle:"From the job<br>to the final payment.",fachScreensCopy:"These are real screens from the prototype in development. Names, addresses and amounts are demonstration data only.",screenProjects:"Projects and their status",screenEstimate:"Detailed estimate",screenSettlement:"Payments and expenses",screenCalendar:"Calendar and reminders",screenPricelist:"Your own service rates",fachRoadTitle:"From prototype to the building site.",fachRoadCopy:"First we test the complete workflow with real scenarios. We will announce the first release after testing is complete.",fachPrototype:"Complete prototype",fachPrototypeCopy:"Client, measurements, estimate, scope, materials, calendar and settlement work together.",fachTesting:"Everyday workflow tests",fachTestingCopy:"We are checking whether the essential information can be added quickly, including on the move.",fachNext:"Refinement and first release",fachNextCopy:"Changes after testing, document preparation and a stable version of the app.",fachQuestions:"Frequently asked questions.",fachFaqReady:"Is Fachmetr available now?",fachFaqReadyAnswer:"Not yet. The working prototype is being tested and refined before its first release.",fachFaqWho:"Who is the app for?",fachFaqWhoAnswer:"Primarily solo tradespeople and small renovation crews managing several jobs who want clear finances and scope.",fachFaqOffline:"Does the app need internet access?",fachFaqOfflineAnswer:"The current prototype stores data locally and works without a constant internet connection.",fachFaqData:"Where is the data stored?",fachFaqDataAnswer:"In the current version, on the user's device. The app does not require an account or cloud sync.",fachCta:"Fachmetr is being built in practice.",fachCtaCopy:"Follow Apscento or write to us if you want to hear when testing begins.",fachDownloadEyebrow:"Test build",fachDownloadTitle:"Try Fachmetr on your phone.",fachDownloadCopy:"Download the APK installer and test the app offline on Android — no computer, no account needed.",fachDownloadBtn:"Download APK ↓",fachDownloadNote:"Android will ask you to allow installs from an unknown source — that is expected outside Google Play."})
Object.assign(translations.uk,{fachHeadline:"Від замірів до розрахунку. Увесь ремонт в одному місці.",fachSummary:"Fachmetr допомагає майстрам готувати кошториси й контролювати обсяг робіт, матеріали та терміни — навіть без інтернету.",discoverFach:"Дізнатися про Fachmetr",september2026:"Вересень 2026",updateFachTitle:"Повний процес ремонту вже працює в прототипі",updateFachCopy:"Клієнти, заміри, кошториси, матеріали, розрахунки й календар уже поєднані в одному мобільному процесі. Тепер ми перевіряємо його на практиці.",navScreens:"Екрани",fachHero:"Ремонт під контролем.<br>Від першого заміру.",fachLead:"Fachmetr створюється для майстрів, які хочуть тримати кошторис, обсяг робіт, матеріали, терміни й розрахунок в одному місці.",seeHowItWorks:"Подивитися, як працює",askFach:"Запитати про Fachmetr",forWhom:"Для кого",fachProblem:"Менше пошуку в повідомленнях. Більше часу на якісну роботу.",fachProblemCopy:"Самостійні майстри й невеликі бригади часто ведуть ремонт у блокноті, месенджері та кількох таблицях. Fachmetr об’єднує все в зрозумілу історію замовлення — від клієнта до фінального розрахунку.",fachWhat:"Що впорядковує",fachOnePlace:"Увесь ремонт.<br>Один простий процес.",fachFeatureIntro:"Fachmetr усе ще розробляється. Показані функції описують робочий прототип і поточний напрям продукту.",fachFeatEstimate:"Заміри й кошториси",fachFeatEstimateCopy:"Позиції, кількість і ціни зібрані в зрозумілий кошторис для конкретного клієнта.",fachFeatScope:"Чіткий обсяг робіт",fachFeatScopeCopy:"Погоджена база й подальші зміни показані окремо, щоб домовленості не губилися.",fachFeatMoney:"Матеріали й розрахунки",fachFeatMoneyCopy:"Оплати клієнта, витрати на матеріали й сума до сплати в одному підсумку.",fachFeatCalendar:"Терміни й нагадування",fachFeatCalendarCopy:"Календар допомагає пам’ятати про етапи робіт, платежі та зустрічі.",fachFeatDocs:"Документи для клієнта",fachFeatDocsCopy:"Упорядковані кошториси й підсумки, готові для передавання клієнту.",fachFeatOffline:"Робота без інтернету",fachFeatOfflineCopy:"Поточний проєкт працює локально на пристрої, без облікового запису й постійного доступу до мережі.",fachScreensTitle:"Від замовлення<br>до останньої оплати.",fachScreensCopy:"Це справжні екрани прототипу, що розробляється. Імена, адреси та суми є лише демонстраційними даними.",screenProjects:"Ремонти та їхній статус",screenEstimate:"Детальний кошторис",screenSettlement:"Оплати й витрати",screenCalendar:"Календар і нагадування",screenPricelist:"Власний прайс послуг",fachRoadTitle:"Від прототипу до роботи на об’єкті.",fachRoadCopy:"Спочатку ми перевіряємо весь процес на реальних сценаріях. Термін першого релізу оголосимо після завершення тестів.",fachPrototype:"Повний прототип",fachPrototypeCopy:"Клієнт, заміри, кошторис, обсяг, матеріали, календар і розрахунок працюють разом.",fachTesting:"Тести щоденної роботи",fachTestingCopy:"Перевіряємо, чи можна швидко додавати найважливішу інформацію, зокрема в русі.",fachNext:"Удосконалення й перший реліз",fachNextCopy:"Правки після тестів, підготовка документів і стабільної версії застосунку.",fachQuestions:"Поширені запитання.",fachFaqReady:"Fachmetr уже доступний?",fachFaqReadyAnswer:"Ще ні. Робочий прототип тестується й удосконалюється перед першим релізом.",fachFaqWho:"Для кого створюється застосунок?",fachFaqWhoAnswer:"Насамперед для самостійних майстрів і невеликих ремонтних бригад, які ведуть кілька замовлень і хочуть упорядкувати фінанси та обсяг робіт.",fachFaqOffline:"Застосунку потрібен інтернет?",fachFaqOfflineAnswer:"Поточний прототип зберігає дані локально й працює без постійного підключення до інтернету.",fachFaqData:"Де зберігаються дані?",fachFaqDataAnswer:"У поточній версії — на пристрої користувача. Застосунок не потребує облікового запису або хмарної синхронізації.",fachCta:"Fachmetr створюється на практиці.",fachCtaCopy:"Стеж за Apscento або напиши нам, якщо хочеш дізнатися про початок тестування.",fachDownloadEyebrow:"Тестова версія",fachDownloadTitle:"Спробуй Fachmetr на своєму телефоні.",fachDownloadCopy:"Завантаж файл APK і протестуй застосунок офлайн на Android — без комп'ютера, без облікового запису.",fachDownloadBtn:"Завантажити APK ↓",fachDownloadNote:"Android попросить дозвіл на встановлення з невідомого джерела — це нормально поза Google Play."})
Object.assign(translations.en,{fachRules:"Fachmetr terms",fachPrivacy:"Fachmetr — project and client data",fachPrivacyCopy:"The current prototype does not require an account or login. Information entered by the user — including client details, project addresses, measurements, estimates, payments, expenses and deadlines — is stored locally on the device and is not sent to an Apscento server.",fachPermissions:"Device permissions",fachPermissionsCopy:"The app may ask for camera access to photograph a material receipt, and for notification permission to remind you about dates in the renovation calendar. Receipt photos are stored locally on the device with the rest of the data, and notifications are scheduled locally without needing an internet connection.",fachDocuments:"Documents and responsibility",fachDocumentsCopy:"Documents created in the app — including estimates exported to PDF and the manual backup file — may contain client information. The user is responsible for having a lawful basis to process it, entering accurate information, securing the device and deliberately sharing exported files."})
Object.assign(translations.uk,{fachRules:"Правила Fachmetr",fachPrivacy:"Fachmetr — дані проєктів і клієнтів",fachPrivacyCopy:"Поточний прототип не потребує облікового запису чи входу. Введені дані — зокрема дані клієнтів, адреси об’єктів, заміри, кошториси, платежі, витрати й терміни — зберігаються локально на пристрої та не надсилаються на сервер Apscento.",fachPermissions:"Дозволи пристрою",fachPermissionsCopy:"Застосунок може попросити доступ до камери, щоб сфотографувати чек за матеріали, та дозвіл на сповіщення, щоб нагадати про терміни з календаря ремонту. Фото чеків зберігаються локально на пристрої разом з рештою даних, а сповіщення плануються локально й не потребують інтернету.",fachDocuments:"Документи й відповідальність",fachDocumentsCopy:"Документи, створені в застосунку, — зокрема кошториси, експортовані в PDF, і файл ручної резервної копії — можуть містити дані клієнта. Користувач відповідає за правову підставу їх обробки, точність введеної інформації, безпеку пристрою та свідоме поширення експортованих файлів."})
Object.assign(translations.en,{discoverViv:"Discover VivStat",vivPageHero:"Feeding, weight and climate.<br>Recorded, not remembered.",vivPageLead:"VivStat helps reptile, amphibian and invertebrate keepers keep an enclosure journal — feeding, weight, climate and sheds — and reminds them of what matters, even without internet access.",askViv:"Ask about VivStat",whyViv:"Why VivStat",vivProblem:"A journal and memory cannot keep up with a terrarium's rhythm.",vivProblemCopy:"Feeding once a week, once a month or once every few months — every species has its own rhythm. VivStat is meant to track that rhythm for the keeper, instead of leaving it to memory or a note by the enclosure.",vivScreensTitle:"Real screens.<br>A real terrarium collection.",vivScreensCopy:"These are real screens from the prototype in development. Animal names and readings are example data.",screenTank:"Enclosure and climate",screenAnalytics:"Weight and statistics",screenPlan:"Care plan and reminders",screenJournal:"Event journal",vivWhat:"What VivStat does",vivOnePlace:"One journal.<br>The whole collection.",vivFeatureIntro:"VivStat is still being developed. The features below already work in the prototype.",featVivProfile:"Enclosure and animal profiles",featVivProfileCopy:"Species, biome, acquisition date and climate targets recorded for every animal.",featVivEntries:"Quick journal entries",featVivEntriesCopy:"Feeding, weight, climate, sheds and notes added in seconds — editable and removable at any time.",featVivReminders:"Feeding reminders",featVivRemindersCopy:"A notification at a set time, calculated from the last feeding and the chosen interval — also for custom reminders in the care plan.",featVivBackup:"Backup and offline use",featVivBackupCopy:"Data lives on the phone with no account and no internet; one export lets you take it to another device.",vivRoadTitle:"From a phone journal to reliable reminders.",vivRoadCopy:"First we are checking how reliable reminders are on a real phone. We will announce the first release once testing is complete.",vivPrototype:"Working prototype",vivPrototypeCopy:"Enclosures, animals, the journal, reminders and backup all work together on a local database.",vivTesting:"Reminder testing",vivTestingCopy:"We are checking how reliably feeding notifications survive a restart, sleep mode and battery restrictions on a real phone.",vivNext:"Species presets and first release",vivNextCopy:"Climate norms for common species and preparation for the first public version.",vivFaqReady:"Is VivStat available yet?",vivFaqReadyAnswer:"Not publicly yet. The prototype is being tested on a single device before its first release.",vivFaqWho:"Which animals is VivStat for?",vivFaqWhoAnswer:"Mainly reptiles, amphibians and invertebrates — snakes, lizards, tortoises, tarantulas and other terrarium residents.",vivFaqOffline:"Does the app need internet access?",vivFaqOfflineAnswer:"No. Data is stored locally on the device and the app works without a network connection.",vivFaqData:"Where is the data stored?",vivFaqDataAnswer:"On the user's device, with no account or cloud. A backup can be exported and imported manually.",vivCta:"VivStat grows with your collection.",vivCtaCopy:"Follow Apscento or write to us if you want to hear when testing begins."})
Object.assign(translations.uk,{discoverViv:"Дізнатися про VivStat",vivPageHero:"Годування, вага і клімат.<br>Записані, а не запам'ятані.",vivPageLead:"VivStat допомагає власникам рептилій, амфібій і безхребетних вести щоденник тераріуму — годування, вагу, клімат і линьки — та нагадує про важливе, навіть без інтернету.",askViv:"Запитати про VivStat",whyViv:"Навіщо VivStat",vivProblem:"Щоденник і пам'ять не встигають за ритмом тераріуму.",vivProblemCopy:"Годування раз на тиждень, раз на місяць або раз на кілька місяців — кожен вид має свій ритм. VivStat має стежити за цим ритмом замість власника, а не залишати це пам'яті чи записці біля тераріуму.",vivScreensTitle:"Справжні екрани.<br>Справжня колекція.",vivScreensCopy:"Це справжні екрани прототипу, що розробляється. Імена тварин і показники є прикладами.",screenTank:"Тераріум і клімат",screenAnalytics:"Вага і статистика",screenPlan:"План догляду й нагадування",screenJournal:"Щоденник подій",vivWhat:"Що робить VivStat",vivOnePlace:"Один щоденник.<br>Уся колекція.",vivFeatureIntro:"VivStat усе ще розробляється. Наведені нижче функції вже працюють у прототипі.",featVivProfile:"Профілі тераріуму й тварин",featVivProfileCopy:"Вид, біом, дата придбання та цілі клімату записані для кожної тварини.",featVivEntries:"Швидкий запис до щоденника",featVivEntriesCopy:"Годування, вага, клімат, линька й нотатки додаються за секунди — з можливістю редагування й видалення будь-коли.",featVivReminders:"Нагадування про годування",featVivRemindersCopy:"Сповіщення о певній годині, розраховане з останнього годування та встановленого інтервалу — також для власних нагадувань у Плані.",featVivBackup:"Резервна копія й офлайн-режим",featVivBackupCopy:"Дані живуть на телефоні без облікового запису й інтернету; один експорт дозволяє перенести їх на інший пристрій.",vivRoadTitle:"Від щоденника в телефоні до перевірених нагадувань.",vivRoadCopy:"Спочатку перевіряємо надійність нагадувань на реальному телефоні. Термін першого релізу оголосимо після завершення тестів.",vivPrototype:"Робочий прототип",vivPrototypeCopy:"Тераріуми, тварини, щоденник, нагадування й резервна копія працюють разом на локальній базі даних.",vivTesting:"Тестування нагадувань",vivTestingCopy:"Перевіряємо надійність сповіщень про годування на реальному телефоні — перезапуск, режим сну, обмеження батареї.",vivNext:"Пресети видів і перший реліз",vivNextCopy:"Норми клімату для популярних видів і підготовка до першої публічної версії.",vivFaqReady:"VivStat уже доступний?",vivFaqReadyAnswer:"Ще не публічно. Прототип тестується на одному пристрої перед першим релізом.",vivFaqWho:"Для яких тварин призначений VivStat?",vivFaqWhoAnswer:"Насамперед для рептилій, амфібій і безхребетних — вужів, ящірок, черепах, павуків-птахоїдів та інших мешканців тераріуму.",vivFaqOffline:"Застосунку потрібен інтернет?",vivFaqOfflineAnswer:"Ні. Дані зберігаються локально на пристрої, і застосунок працює без підключення до мережі.",vivFaqData:"Де зберігаються дані?",vivFaqDataAnswer:"На пристрої користувача, без облікового запису й хмари. Резервну копію можна експортувати та імпортувати вручну.",vivCta:"VivStat росте разом із колекцією.",vivCtaCopy:"Стеж за Apscento або напиши нам, якщо хочеш дізнатися про початок тестування."})
Object.assign(translations.en,{privacyPolicy:"Website privacy",appsGeneralNav:"Shared rules",vivRulesNav:"VivStat terms",yourRightsNav:"Your rights",securityNav:"Security",legalIntro:"This document explains in plain language what data the Apscento website processes and how our apps work: DriverStat, Fachmetr and VivStat. Apscento is a one-person project — with no cloud, no user accounts and no internal servers where your data could end up. We update this document as each project develops.",legalDraft:"DriverStat, Fachmetr and VivStat are all still under active development — Fachmetr already has a test APK build available, and the other two are in closed testing. The description below reflects how they currently work and will be reviewed again before each public release on Google Play or the App Store, especially if features, permissions or data storage change.",websitePrivacy:"Privacy on the Apscento website",dataController:"Data controller",dataControllerCopy:"Under the GDPR, the data controller for the Apscento website and all Apscento apps is Piotr, who runs Apscento as a one-person project. Contact: apscento@gmail.com.",websitePrivacyCopy:"apscento.github.io is a static information website — it has no forms, user accounts, advertising or first-party analytics. The site is hosted on GitHub Pages (GitHub, Inc.); the hosting provider may record basic server-level technical data (e.g. IP address, browser type, request time) under its own GitHub privacy policy — Apscento has no access to those logs and does not process them.",cookiesTitle:"Cookies and browser storage",cookiesCopy:"The website does not use cookies for tracking or advertising. We save your chosen language (Polish/English/Ukrainian) locally in your browser (localStorage) so it is remembered on your next visit — this stays only on your device and is never sent anywhere.",appsGeneral:"Shared rules for Apscento apps",appsGeneralCopy:"DriverStat, Fachmetr and VivStat all work the same way: there is no Apscento server for your data to be sent to, because no such server exists. Everything you enter stays in a local database on your phone.",appsNoAccount:"No accounts, no cloud",appsNoAccountCopy:"None of the apps require registration, login or an account. There is no sync between devices — the only way to move your data is the manual backup export and import described separately for each app.",appsNoTracking:"No ads, no tracking",appsNoTrackingCopy:"The apps contain no advertising, analytics tools or third-party trackers. System permissions (notifications, camera) are requested only when a specific feature needs them, and are used only for that feature — never to collect or transmit data.",appsUninstall:"Uninstalling an app",appsUninstallCopy:"Uninstalling an app deletes its local database from your phone, subject to the device's own system backups (e.g. Google or Apple), which Apscento does not control.",driverPrivacy:"DriverStat — data and how calculations work",localDataCopy:"DriverStat does not require an account or login. Information you enter — shifts, rates, fuel expenses, servicing and repairs, vehicle details and fleet settlement settings — stays in a local database on your phone and is never sent to any server.",permissionsCopy:"The app only asks for notification permission once you turn on reminders in Settings — not on first launch. Notifications remind you to log a shift and about an upcoming insurance (OC) expiry; they are scheduled locally on the device and survive a phone restart. They never send or receive any data over the internet.",driverBackup:"Backup",driverBackupCopy:"In Settings you can export all your data (shifts, refuelling, repairs, settings) to a single CSV file in a location you choose, and import it back later. Apscento has no access to that file — it stays wherever you save it.",controlDataCopy:"You can edit and delete data directly in the app. Uninstalling the app removes locally stored data, subject to the device's own system backups, which Apscento may not control.",fachPrivacy:"Fachmetr — client and project data",fachPrivacyCopy:"Fachmetr does not require an account or login. Information you enter — including your own clients' details (name/company, phone, email, project address, optional billing address, notes), measurements, price list, estimates, scope changes, payments, material expenses, photos and the calendar — is stored only locally on your device.",fachController:"Who controls your clients' data",fachControllerCopy:"You decide what data about your clients you enter into Fachmetr, and you — not Apscento — are the data controller for that data under the GDPR in relation to your clients. Fachmetr is a tool for storing it on your phone; Apscento has no access to it, because it is never sent anywhere.",fachPermissionsCopy:"The app may ask for camera access — for photos of the job and material receipts, stored locally with the rest of your data — and for notification permission, to remind you about dates and custom reminders in the renovation calendar. Notifications are scheduled locally and do not need an internet connection.",fachDocumentsCopy:"Estimates exported to PDF may include client details as well as your own details entered in Settings (name/company, phone, email, tax ID, logo, bank account number). You are responsible for having a lawful basis to process your client's data, for the accuracy of what you enter, for securing your device, and for deliberately sharing exported files.",fachBackup:"Backup",fachBackupCopy:"You can export a single file containing all your data and photos, and import it on another device — manually, with no account or cloud.",fachDistribution:"Installing outside Google Play",fachDistributionCopy:"The current test build of Fachmetr is distributed as an APK file you download directly from the Apscento website (GitHub Releases), outside Google Play — Android will ask you to allow installs from an unknown source. This kind of install does not go through Google Play's own vetting, so only download the file from the official apscento.github.io website.",vivPrivacy:"VivStat — terrarium journal",vivPrivacyCopy:"VivStat does not require an account or login. Information you enter — enclosures, animals (species, acquisition date, weight), feedings, climate readings, sheds and notes — is stored only locally on your device, in a database Apscento has no access to.",vivPermissions:"Device permissions",vivPermissionsCopy:"The app asks for notification permission to remind you about feeding — the timing is calculated from the last feeding and the interval you set for that animal — and for custom reminders saved in the care plan. Notifications are scheduled locally and do not need internet access. The app does not currently use the camera; animal photos are not yet supported.",vivBackup:"Backup",vivBackupCopy:"In Settings you can export the whole database to a file through the system “Share” sheet, and import it back after picking a file — no account or cloud involved.",vivLinks:"Links inside the app",vivLinksCopy:"The “About” section in Settings links to the VivStat website and to this document; both open in your system browser and do not pass any data from the app.",yourRights:"Your rights (GDPR)",yourRightsIntro:"Because the data in these apps lives only on your device, you already have full, direct control over it — you can review, correct, export or delete it at any time, in the app itself or by uninstalling it.",yourRightsEmail:"If you email us, you have the right to access your data, to have it corrected or deleted, to restrict its processing, to data portability and to object to processing — write to apscento@gmail.com.",yourRightsComplaint:"If you live in the European Union, you also have the right to lodge a complaint with a supervisory authority — in Poland this is the President of the Personal Data Protection Office (uodo.gov.pl). If other data protection laws apply to you, write to us — we will try to help, even though Apscento has no formal legal department.",securityTitle:"Security and children",securityData:"Data security",securityDataCopy:"The biggest safeguard is the design itself: your data never leaves your device, so there is no Apscento server that could be attacked or leaked from. You are responsible for securing your phone (screen lock, system updates) and any backup files you export yourself. The Apscento website uses an encrypted HTTPS connection.",childrenTitle:"Children",childrenCopy:"The website and apps are not directed at children under 16, and we do not knowingly collect data from them — and since nothing reaches our server, we have no way to store it either way. If a guardian believes a child has entered data in an app, it can be deleted directly in the app.",legalReview:"This document will be updated as the website and apps develop — the date at the top always shows the last update. It organises the information currently available about the projects, but it is not legal advice. Before DriverStat, Fachmetr and VivStat are publicly released, they will be reviewed again against each app's actual operation, distribution platform and the publisher's identification details."})
Object.assign(translations.uk,{privacyPolicy:"Конфіденційність сайту",appsGeneralNav:"Спільні правила",vivRulesNav:"Правила VivStat",yourRightsNav:"Твої права",securityNav:"Безпека",legalIntro:"Цей документ простою мовою пояснює, які дані обробляє сайт Apscento та як працюють наші застосунки: DriverStat, Fachmetr і VivStat. Apscento — це проєкт однієї людини: без хмари, облікових записів користувачів і внутрішніх серверів, куди могли б потрапити твої дані. Ми оновлюємо цей документ разом із розвитком кожного проєкту.",legalDraft:"DriverStat, Fachmetr і VivStat усе ще активно розробляються — Fachmetr уже має тестову версію APK для завантаження, а два інші застосунки проходять закрите тестування. Опис нижче відображає їхню поточну роботу і буде повторно перевірений перед кожним публічним релізом у Google Play чи App Store, особливо якщо зміняться функції, дозволи або спосіб зберігання даних.",websitePrivacy:"Конфіденційність сайту Apscento",dataController:"Адміністратор даних",dataControllerCopy:"Відповідно до GDPR адміністратором даних сайту та всіх застосунків Apscento є Piotr, який веде Apscento як проєкт однієї людини. Контакт: apscento@gmail.com.",websitePrivacyCopy:"apscento.github.io — це статичний інформаційний сайт: без форм, облікових записів, реклами чи власної аналітики. Сайт розміщено на GitHub Pages (GitHub, Inc.); постачальник хостингу може зберігати базові технічні дані сервера (наприклад, IP-адресу, тип браузера, час запиту) згідно з власною політикою конфіденційності GitHub — Apscento не має доступу до цих журналів і не обробляє їх.",cookiesTitle:"Cookie-файли та пам'ять браузера",cookiesCopy:"Сайт не використовує cookie-файли для відстеження чи реклами. Обрану мову (польську/англійську/українську) ми зберігаємо локально у твоєму браузері (localStorage), щоб запам'ятати її для наступного візиту — ця інформація залишається лише на твоєму пристрої й нікуди не надсилається.",appsGeneral:"Спільні правила для застосунків Apscento",appsGeneralCopy:"DriverStat, Fachmetr і VivStat працюють за однаковим принципом: у них немає сервера Apscento, куди надсилалися б твої дані, — бо такого сервера просто не існує. Усе, що ти вводиш, залишається в локальній базі даних на твоєму телефоні.",appsNoAccount:"Без облікових записів і хмари",appsNoAccountCopy:"Жоден із застосунків не потребує реєстрації, входу чи облікового запису. Немає синхронізації між пристроями — єдиний спосіб перенести дані — це ручний експорт та імпорт резервної копії, описаний окремо для кожного застосунку.",appsNoTracking:"Без реклами й стеження",appsNoTrackingCopy:"Застосунки не містять реклами, аналітичних інструментів чи трекерів третіх сторін. Системні дозволи (сповіщення, камера) запитуються лише тоді, коли їх потребує конкретна функція, і використовуються виключно для її роботи — а не для збирання чи передавання даних.",appsUninstall:"Видалення застосунку",appsUninstallCopy:"Видалення застосунку стирає його локальну базу даних із телефону, за винятком системних резервних копій пристрою (наприклад, Google чи Apple), на які Apscento не впливає.",driverPrivacy:"DriverStat — дані та як працюють розрахунки",localDataCopy:"DriverStat не потребує облікового запису чи входу. Введені тобою дані — зміни, тарифи, витрати на пальне, сервіс і ремонти, дані автомобіля та налаштування розрахунків флоту — залишаються в локальній базі даних на телефоні й ніколи не надсилаються на жоден сервер.",permissionsCopy:"Застосунок запитує дозвіл на сповіщення лише тоді, коли ти вмикаєш нагадування в Налаштуваннях, а не під час першого запуску. Сповіщення нагадують внести зміну та про наближення завершення ОСЦПВ (OC), плануються локально на пристрої й переживають перезапуск телефону. Вони не надсилають і не отримують жодних даних через інтернет.",driverBackup:"Резервна копія",driverBackupCopy:"У Налаштуваннях можна експортувати всі дані (зміни, заправки, ремонти, налаштування) в один файл CSV у місце, яке ти сам обереш, і згодом імпортувати його назад. Apscento не має доступу до цього файлу — він залишається там, де ти його зберіг.",controlDataCopy:"Ти можеш редагувати й видаляти дані прямо в застосунку. Видалення застосунку прибирає локально збережені дані, за винятком системних резервних копій пристрою, на які Apscento може не впливати.",fachPrivacy:"Fachmetr — дані клієнтів і ремонтів",fachPrivacyCopy:"Fachmetr не потребує облікового запису чи входу. Дані, які ти вводиш, — зокрема дані твоїх клієнтів (ім'я/назва, телефон, e-mail, адреса об'єкта, необов'язкова адреса розрахунків, нотатки), заміри, прайс-лист, кошториси, зміни обсягу робіт, оплати, витрати на матеріали, фото й календар — зберігаються лише локально на твоєму пристрої.",fachController:"Хто адмініструє дані твоїх клієнтів",fachControllerCopy:"Саме ти вирішуєш, які дані своїх клієнтів вносити до Fachmetr, і саме ти — а не Apscento — є адміністратором цих даних відповідно до GDPR щодо своїх клієнтів. Fachmetr — це інструмент для їх зберігання на твоєму телефоні; Apscento не має до них доступу, бо вони нікуди не надсилаються.",fachPermissionsCopy:"Застосунок може попросити доступ до камери — для фото ремонту та чеків за матеріали, які зберігаються локально разом з рештою даних, — а також дозвіл на сповіщення, щоб нагадати про терміни й власні нагадування з календаря ремонту. Сповіщення плануються локально і не потребують інтернету.",fachDocumentsCopy:"Кошториси, експортовані в PDF, можуть містити дані клієнта, а також твої дані, вказані в Налаштуваннях (ім'я/назва фірми, телефон, e-mail, податковий номер, логотип, номер рахунку). Ти відповідаєш за правову підставу обробки даних клієнта, точність введеної інформації, безпеку пристрою та свідоме поширення експортованих файлів.",fachBackup:"Резервна копія",fachBackupCopy:"Ти можеш експортувати один файл з усіма даними й фото та імпортувати його на іншому пристрої — вручну, без облікового запису чи хмари.",fachDistribution:"Встановлення поза Google Play",fachDistributionCopy:"Поточна тестова версія Fachmetr поширюється як файл APK, який завантажується безпосередньо з сайту Apscento (GitHub Releases), поза Google Play — Android попросить дозвіл на встановлення з невідомого джерела. Таке встановлення не проходить перевірку Google Play в той самий спосіб, тому завантажуй файл лише з офіційного сайту apscento.github.io.",vivPrivacy:"VivStat — щоденник тераріуму",vivPrivacyCopy:"VivStat не потребує облікового запису чи входу. Дані, які ти вводиш, — тераріуми, тварини (вид, дата придбання, вага), годування, показники клімату, линьки й нотатки — зберігаються лише локально на твоєму пристрої, у базі даних, до якої Apscento не має доступу.",vivPermissions:"Дозволи пристрою",vivPermissionsCopy:"Застосунок запитує дозвіл на сповіщення, щоб нагадувати про годування — термін розраховується з останнього годування та встановленого для тварини інтервалу, — а також для власних нагадувань, збережених у Плані догляду. Сповіщення плануються локально й не потребують інтернету. Наразі застосунок не використовує камеру; фото мешканців ще не підтримуються.",vivBackup:"Резервна копія",vivBackupCopy:"У Налаштуваннях можна експортувати всю базу даних у файл через системне вікно «Поділитися» та імпортувати її назад після вибору файлу — без облікового запису й хмари.",vivLinks:"Посилання в застосунку",vivLinksCopy:"Розділ «Про застосунок» у Налаштуваннях містить посилання на сайт VivStat і цей документ; обидва відкриваються в системному браузері й не передають жодних даних із застосунку.",yourRights:"Твої права (GDPR)",yourRightsIntro:"Оскільки дані в застосунках живуть лише на твоєму пристрої, ти вже маєш над ними повний і прямий контроль — можеш будь-коли переглянути, виправити, експортувати чи видалити їх у самому застосунку або видаливши його.",yourRightsEmail:"Якщо ти напишеш нам на e-mail, ти маєш право на доступ до своїх даних, їх виправлення, видалення, обмеження обробки, перенесення та заперечення проти обробки — пиши на apscento@gmail.com.",yourRightsComplaint:"Якщо ти проживаєш у Європейському Союзі, ти також маєш право подати скаргу до наглядового органу — у Польщі це Голова Управління захисту персональних даних (uodo.gov.pl). Якщо на тебе поширюються інші закони про захист даних, напиши нам — ми спробуємо допомогти, попри те що Apscento не має формального юридичного відділу.",securityTitle:"Безпека та діти",securityData:"Безпека даних",securityDataCopy:"Найбільший захист — це сам підхід: твої дані не залишають пристрій, тому немає сервера Apscento, який можна було б атакувати чи з якого могли б витекти дані. Ти відповідаєш за захист телефону (блокування екрана, оновлення системи) та файлів резервних копій, які експортуєш сам. Сайт Apscento використовує зашифроване з'єднання HTTPS.",childrenTitle:"Діти",childrenCopy:"Сайт і застосунки не призначені для дітей віком до 16 років, і ми свідомо не збираємо їхні дані — а оскільки нічого не потрапляє на наш сервер, ми й не маємо як їх зберігати. Якщо опікун вважає, що дитина ввела дані в застосунку, їх можна самостійно видалити прямо в застосунку.",legalReview:"Цей документ оновлюватиметься разом із розвитком сайту та застосунків — дата вгорі завжди показує останнє оновлення. Він упорядковує наявну інформацію про проєкти, але не є юридичною консультацією. Перед публічним релізом DriverStat, Fachmetr і VivStat вони будуть повторно перевірені відповідно до фактичної роботи кожного застосунку, платформи поширення та ідентифікаційних даних видавця."})
const defaultText={};document.querySelectorAll('[data-i18n]').forEach(el=>defaultText[el.dataset.i18n]=el.innerHTML)
const setLanguage=lang=>{const copy=lang==='pl'?defaultText:translations[lang];if(!copy)return;document.documentElement.lang=lang;document.querySelectorAll('[data-i18n]').forEach(el=>{if(copy[el.dataset.i18n])el.innerHTML=copy[el.dataset.i18n]});document.querySelectorAll('[data-i18n-aria]').forEach(el=>{const value=copy[el.dataset.i18nAria]||defaultText[el.dataset.i18nAria];if(value)el.setAttribute('aria-label',value)});document.querySelectorAll('[data-lang]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.lang===lang)));localStorage.setItem('apscento-language',lang)}
document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>setLanguage(button.dataset.lang)))
const preferred=localStorage.getItem('apscento-language')||({pl:'pl',en:'en',uk:'uk'}[navigator.language.slice(0,2)]||'pl');setLanguage(preferred)
const toggle=document.querySelector('.nav-toggle'),links=document.querySelector('.nav-links');if(toggle&&links){toggle.addEventListener('click',()=>{const open=links.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))});links.addEventListener('click',()=>{links.classList.remove('open');toggle.setAttribute('aria-expanded','false')})}
